"use client";

import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useRouter } from "next/navigation";
import { getApiUrl } from "@/lib/config";

export interface SearchResult {
  id: string;
  type: "chat" | "journal" | "mood" | "cbt" | "assessment";
  title: string;
  snippet: string;
  timestamp: string;
  link: string;
}

interface GlobalSearchProps {
  isOpen: boolean;
  onClose: () => void;
  userId?: string;
}

const CATEGORIES = [
  { id: "all", label: "All", icon: "✨" },
  { id: "chats", label: "Chats", icon: "💬" },
  { id: "journal", label: "Journal", icon: "📝" },
  { id: "mood", label: "Mood Log", icon: "😊" },
  { id: "cbt", label: "CBT Worksheets", icon: "🧠" },
];

export default function GlobalSearch({ isOpen, onClose, userId }: GlobalSearchProps) {
  const router = useRouter();
  const [query, setQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState("all");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);

  const API_URL = getApiUrl();

  useEffect(() => {
    if (!query.trim() || !userId) {
      const timer = setTimeout(() => setResults([]), 0);
      return () => clearTimeout(timer);
    }

    const timer = setTimeout(async () => {
      setLoading(true);
      try {
        const res = await fetch(
          `${API_URL}/search/${userId}?q=${encodeURIComponent(query)}&category=${activeCategory}`
        );
        if (res.ok) {
          const data = await res.json();
          setResults(data.results || []);
        }
      } catch (err) {
        console.error("[GlobalSearch] Error fetching results:", err);
      } finally {
        setLoading(false);
      }
    }, 250);

    return () => clearTimeout(timer);
  }, [query, activeCategory, userId, API_URL]);

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <div
        style={{
          position: "fixed",
          inset: 0,
          zIndex: 9999,
          background: "rgba(0, 0, 0, 0.7)",
          backdropFilter: "blur(12px)",
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "center",
          paddingTop: "10vh",
        }}
        onClick={onClose}
      >
        <motion.div
          initial={{ opacity: 0, scale: 0.95, y: -20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: -20 }}
          onClick={(e) => e.stopPropagation()}
          style={{
            width: "90%",
            maxWidth: 640,
            background: "rgba(15, 23, 42, 0.95)",
            border: "1px solid var(--border-secondary)",
            borderRadius: 20,
            boxShadow: "0 20px 50px rgba(0,0,0,0.6)",
            overflow: "hidden",
            display: "flex",
            flexDirection: "column",
            maxHeight: "75vh",
          }}
        >
          {/* Search Header Bar */}
          <div style={{ padding: "16px 20px", borderBottom: "1px solid var(--border-secondary)", display: "flex", alignItems: "center", gap: 12 }}>
            <span style={{ fontSize: 18 }}>🔍</span>
            <input
              type="text"
              placeholder="Search chats, journal, mood entries, CBT worksheets..."
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              autoFocus
              style={{
                flex: 1,
                background: "transparent",
                border: "none",
                outline: "none",
                color: "var(--text-primary)",
                fontSize: 15,
                fontFamily: "var(--font-sans)",
              }}
            />
            {query && (
              <button
                onClick={() => setQuery("")}
                style={{ background: "none", border: "none", color: "var(--text-tertiary)", cursor: "pointer", fontSize: 14 }}
              >
                ✕
              </button>
            )}
            <button
              onClick={onClose}
              style={{
                padding: "4px 8px",
                borderRadius: 8,
                background: "var(--bg-glass)",
                border: "1px solid var(--border-secondary)",
                color: "var(--text-tertiary)",
                fontSize: 11,
                cursor: "pointer",
              }}
            >
              ESC
            </button>
          </div>

          {/* Category Filters */}
          <div style={{ padding: "10px 20px", display: "flex", gap: 6, borderBottom: "1px solid var(--border-secondary)", overflowX: "auto" }}>
            {CATEGORIES.map((cat) => {
              const isSel = activeCategory === cat.id;
              return (
                <button
                  key={cat.id}
                  onClick={() => setActiveCategory(cat.id)}
                  style={{
                    padding: "6px 12px",
                    borderRadius: 10,
                    background: isSel ? "rgba(34,197,94,0.2)" : "var(--bg-glass)",
                    border: isSel ? "1px solid rgba(34,197,94,0.4)" : "1px solid var(--border-secondary)",
                    color: isSel ? "#22c55e" : "var(--text-secondary)",
                    fontSize: 12,
                    fontWeight: 600,
                    cursor: "pointer",
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                    whiteSpace: "nowrap",
                  }}
                >
                  <span>{cat.icon}</span>
                  <span>{cat.label}</span>
                </button>
              );
            })}
          </div>

          {/* Results List */}
          <div style={{ flex: 1, overflowY: "auto", padding: 12, display: "flex", flexDirection: "column", gap: 8 }} className="custom-scrollbar">
            {loading && (
              <div style={{ padding: 30, textAlign: "center", color: "var(--text-secondary)", fontSize: 13 }}>
                Searching your mental health records...
              </div>
            )}

            {!loading && query.trim() && results.length === 0 && (
              <div style={{ padding: 40, textAlign: "center", color: "var(--text-tertiary)", fontSize: 13 }}>
                No results found for &quot;{query}&quot;.
              </div>
            )}

            {!loading && !query.trim() && (
              <div style={{ padding: 40, textAlign: "center", color: "var(--text-tertiary)", fontSize: 13 }}>
                Type a keyword above to search across your platform data.
              </div>
            )}

            {!loading && results.map((item) => (
              <motion.div
                key={`${item.type}-${item.id}`}
                whileHover={{ scale: 1.01, x: 2 }}
                onClick={() => {
                  onClose();
                  router.push(item.link);
                }}
                style={{
                  padding: "12px 16px",
                  borderRadius: 14,
                  background: "var(--bg-glass)",
                  border: "1px solid var(--border-secondary)",
                  cursor: "pointer",
                  display: "flex",
                  flexDirection: "column",
                  gap: 4,
                }}
              >
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: "var(--text-primary)", display: "flex", alignItems: "center", gap: 8 }}>
                    <span>{getTypeIcon(item.type)}</span>
                    <span>{item.title}</span>
                  </div>
                  <span style={{ fontSize: 10, color: "var(--text-tertiary)" }}>
                    {item.timestamp ? new Date(item.timestamp).toLocaleDateString() : ""}
                  </span>
                </div>
                {item.snippet && (
                  <div style={{ fontSize: 12, color: "var(--text-secondary)", lineHeight: 1.4 }}>
                    {item.snippet}
                  </div>
                )}
              </motion.div>
            ))}
          </div>
        </motion.div>
      </div>
    </AnimatePresence>
  );
}

function getTypeIcon(type: string) {
  switch (type) {
    case "chat": return "💬";
    case "journal": return "📝";
    case "mood": return "😊";
    case "cbt": return "🧠";
    default: return "📄";
  }
}
